#[test]
fn original_private_windows_and_boundary_oracles_remain_distinct_in_all_four_runs() {
    let probes: Value = serde_json::from_str(PRIVATE).unwrap();
    let mut failures = 0;
    let mut applications = 0;
    for probe in probes.as_array().unwrap() {
        let case = &probe["case"];
        let plan = plan(case);
        for oracle in probe["oracles"].as_array().unwrap() {
            assert_eq!(oracle["counters"].as_array().unwrap().len(), 1);
            let failed = !oracle["errors"].as_array().unwrap().is_empty();
            let mut rejected = false;
            for (index, input) in case["values"].as_array().unwrap().iter().enumerate() {
                let input = input.as_str().map(hex);
                let original = input.clone();
                let actual = apply(
                    plan,
                    input.as_deref(),
                    input.as_ref().map_or(0, Vec::len),
                    1024,
                );
                applications += 1;
                if failed {
                    if let Err(error) = actual {
                        assert_eq!(
                            serde_json::to_value(diagnostic(error)).unwrap(),
                            oracle["errors"][0],
                            "{}",
                            case["name"]
                        );
                        rejected = true;
                    } else {
                        assert!(
                            input.is_none(),
                            "{} unexpected successful challenge",
                            case["name"]
                        );
                        assert_eq!(actual.unwrap(), None);
                    }
                } else {
                    let expected = oracle["native"][index].as_str().map(hex);
                    assert_eq!(
                        actual.unwrap().map(projected_bytes),
                        expected,
                        "{}",
                        case["name"]
                    );
                    assert_eq!(
                        apply(
                            plan,
                            input.as_deref(),
                            input.as_ref().map_or(0, Vec::len),
                            expected.as_ref().map_or(0, Vec::len)
                        )
                        .unwrap()
                        .map(projected_bytes),
                        expected
                    );
                }
                assert_eq!(input, original);
            }
            if failed {
                failures += 1;
                assert!(rejected);
                assert!(oracle["native"].as_array().unwrap().is_empty());
            }
        }
    }
    assert_eq!(probes.as_array().unwrap().len(), 704);
    assert_eq!(failures, 2312);
    assert_eq!(applications, 5632);
}
fn unpack(value: &Value) -> Vec<u8> {
    value
        .as_array()
        .unwrap()
        .iter()
        .flat_map(|pair| {
            std::iter::repeat_n(
                pair[0].as_u64().unwrap() as u8,
                pair[1].as_u64().unwrap() as usize,
            )
        })
        .collect()
}
#[test]
fn every_valid_bmp_scalar_matches_each_original_bulk_codepage_output() {
    let mut input = Vec::new();
    for unit in 0..=u16::MAX {
        if let Some(ch) = char::from_u32(u32::from(unit)) {
            let mut encoded = [0; 4];
            input.extend_from_slice(ch.encode_utf8(&mut encoded).as_bytes());
        }
    }
    let original = input.clone();
    let oracle: Value = serde_json::from_str(BMP).unwrap();
    assert_eq!(oracle.as_array().unwrap().len(), 4);
    for run in oracle.as_array().unwrap() {
        assert_eq!(run.as_array().unwrap().len(), 2);
        for captured in run.as_array().unwrap() {
            let target = if captured["target"] == "cp1251" {
                EncodingIdentity::Cp1251
            } else {
                EncodingIdentity::Cp1252
            };
            let plan = Plan::new(
                EncodingIdentity::Utf8,
                SourceForm::Max,
                ProjectionTarget::Native(target),
                Family::Variable,
                Capacity::Max,
            )
            .unwrap();
            let expected = unpack(&captured["native"]);
            assert_eq!(expected.len(), 63488);
            // Independent retained SQL outputs also cover the complete projection
            // API, with no cropping/padding or malformed-decoding behavior.
            let full = msduck_core::ansi_conversion::project(
                EncodingIdentity::Utf8,
                Some(AnsiView::new(EncodingIdentity::Utf8, &input, input.len()).unwrap()),
                ProjectionTarget::Native(target),
                ProjectionLimits {
                    input_bytes: input.len(),
                    output_bytes: expected.len(),
                },
            )
            .unwrap()
            .unwrap();
            assert_eq!(projected_bytes(full), expected);
            assert_eq!(
                apply(plan, Some(&input), input.len(), expected.len())
                    .unwrap()
                    .map(projected_bytes),
                Some(expected)
            );
        }
    }
    assert_eq!(input, original);
}

#[test]
fn prior_admitted_utf8_domains_preserve_each_original_native_unit_and_failure_oracle() {
    let references = [
        include_str!("../../../reference/bulk-character-utf8-boundary.json"),
        include_str!("../../../reference/bulk-character-utf8-bounded-target.json"),
        include_str!("../../../reference/bulk-character-utf8-octet.json"),
        include_str!("../../../reference/bulk-character-utf8-multibyte.json"),
    ];
    let mut observations = 0;
    let mut failures = 0;
    let mut applications = 0;
    for reference in references {
        let f: Value = serde_json::from_str(reference).unwrap();
        for run in f["runs"].as_array().unwrap() {
            for o in run["observations"].as_array().unwrap() {
                let case = &o["case"];
                assert_eq!(case["declared"], "utf8");
                assert_eq!(case["wire"], "utf8");
                let plan = plan(case);
                let errors = o["execution"]["result"]["errors"].as_array().unwrap();
                let expected_rows = o["readback"]["result"]["sets"][1]["rows"]
                    .as_array()
                    .unwrap();
                let mut rejected = false;
                for (index, input) in o["input"].as_array().unwrap().iter().enumerate() {
                    let bytes = input["valueHex"].as_str().map(hex);
                    let result = apply(
                        plan,
                        bytes.as_deref(),
                        bytes.as_ref().map_or(0, Vec::len),
                        1024,
                    );
                    applications += 1;
                    if let Some(error) = errors.first() {
                        assert!(expected_rows.is_empty());
                        if let Err(got) = result {
                            assert_eq!(
                                diagnostic(got),
                                [
                                    error["number"].as_u64().unwrap(),
                                    error["state"].as_u64().unwrap(),
                                    error["class"].as_u64().unwrap()
                                ],
                                "{}",
                                case["name"]
                            );
                            rejected = true;
                        } else {
                            assert!(
                                bytes.is_none(),
                                "{} failed load challenge succeeded",
                                case["name"]
                            );
                        }
                    } else {
                        let expected = expected_rows[index][2]["value"].as_str().map(hex);
                        assert_eq!(
                            result.unwrap().map(projected_bytes),
                            expected,
                            "{}",
                            case["name"]
                        );
                    }
                }
                if !errors.is_empty() {
                    assert!(rejected);
                    failures += 1;
                }
                observations += 1;
            }
        }
    }
    assert_eq!(observations, 4032);
    assert_eq!(applications, 8064);
    assert_eq!(failures, 224);
}

#[test]
fn declarations_input_limits_null_and_final_payload_limits_precede_allocation() {
    use msduck_core::ansi_conversion::capacity::CapacityError;
    use msduck_core::ansi_conversion::{ProjectionError, Resource};
    let limits = ProjectionLimits {
        input_bytes: 0,
        output_bytes: 0,
    };
    for target in [
        ProjectionTarget::SqlUtf16,
        ProjectionTarget::Native(EncodingIdentity::Utf8),
        ProjectionTarget::Native(EncodingIdentity::Cp1251),
    ] {
        for width in [0, usize::MAX] {
            assert!(matches!(
                Plan::new(
                    EncodingIdentity::Utf8,
                    SourceForm::Max,
                    target,
                    Family::Variable,
                    Capacity::Bounded(width)
                ),
                Err(CapacityError::InvalidWidth { .. })
            ));
        }
        assert_eq!(
            Plan::new(
                EncodingIdentity::Utf8,
                SourceForm::Max,
                target,
                Family::Fixed,
                Capacity::Max
            ),
            Err(CapacityError::FixedMax)
        );
        let plan = Plan::new(
            EncodingIdentity::Utf8,
            SourceForm::Bounded,
            target,
            Family::Fixed,
            Capacity::Bounded(2),
        )
        .unwrap();
        assert_eq!(plan.apply(None, limits).unwrap(), None);
        assert_eq!(
            apply(plan, Some(&[0xc2]), 0, 0),
            Err(CapacityError::Projection(ProjectionError::Limit {
                resource: Resource::Input,
                requested: 1,
                maximum: 0
            }))
        );
        let bytes = if target == ProjectionTarget::SqlUtf16 {
            4
        } else {
            2
        };
        assert_eq!(
            apply(plan, Some(&[]), 0, bytes - 1),
            Err(CapacityError::Projection(ProjectionError::Limit {
                resource: Resource::Output,
                requested: bytes,
                maximum: bytes - 1
            }))
        );
        let wanted = if target == ProjectionTarget::SqlUtf16 {
            vec![0x20, 0, 0x20, 0]
        } else {
            vec![0x20, 0x20]
        };
        assert_eq!(
            apply(plan, Some(&[]), 0, bytes)
                .unwrap()
                .map(projected_bytes),
            Some(wanted)
        );
        let wrong = [0x41];
        assert_eq!(
            plan.apply(
                Some(AnsiView::new(EncodingIdentity::Cp1252, &wrong, 1).unwrap()),
                limits
            ),
            Err(CapacityError::Projection(
                ProjectionError::SourceEncodingMismatch {
                    declared: EncodingIdentity::Utf8,
                    actual: EncodingIdentity::Cp1252
                }
            ))
        );
    }
    for opaque in [
        EncodingIdentity::Opaque(1251),
        EncodingIdentity::Opaque(1252),
        EncodingIdentity::Opaque(65001),
    ] {
        assert!(matches!(
            Plan::new(
                opaque,
                SourceForm::Bounded,
                ProjectionTarget::SqlUtf16,
                Family::Variable,
                Capacity::Max
            ),
            Err(CapacityError::Projection(
                ProjectionError::UnsupportedSource(_)
            ))
        ));
        assert!(matches!(
            Plan::new(
                EncodingIdentity::Utf8,
                SourceForm::Bounded,
                ProjectionTarget::Native(opaque),
                Family::Variable,
                Capacity::Max
            ),
            Err(CapacityError::Projection(
                ProjectionError::UnsupportedTarget(_)
            ))
        ));
    }
    // Actual private MAX supplementary-to-Unicode width1 stores empty. Budget
    // the original four input bytes even though the admitted final payload is0.
    let plan = Plan::new(
        EncodingIdentity::Utf8,
        SourceForm::Max,
        ProjectionTarget::SqlUtf16,
        Family::Variable,
        Capacity::Bounded(1),
    )
    .unwrap();
    let original = [0xf0, 0x90, 0x80, 0x80];
    assert_eq!(
        apply(plan, Some(&original), 4, 0)
            .unwrap()
            .map(projected_bytes),
        Some(vec![])
    );
    assert_eq!(
        apply(plan, Some(&original), 3, 0),
        Err(CapacityError::Projection(ProjectionError::Limit {
            resource: Resource::Input,
            requested: 4,
            maximum: 3
        }))
    );
}
